import { useState } from 'react';

export default function App() {
  const [watched, setWatched] = useState(false);
  const [rating, setRating] = useState(0);

  function toggleWatched() {
    setWatched(!watched);
  }

  function addOne() {
    setRating((r) => Math.min(r + 1, 5));
  }

  function addTwo() {
    addOne();
    addOne();
  }

  return (
    <article>
      <h2>Arrival</h2>
      <button id="toggle" aria-pressed={watched} onClick={toggleWatched}>
        {watched ? 'Watched' : 'Mark as watched'}
      </button>
      <p id="rating">Rating: {rating}/5</p>
      <button id="plus" onClick={addOne}>+1</button>
      <button id="plus-two" onClick={addTwo}>+2</button>
    </article>
  );
}
